// D931 (after PR 159's review, L2): the pre-deploy migration check refuses a deploy whose database lacks a migration the
// code reads, and whenever it can't tell (fail closed); the required file is each app's latest migration.
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { repoRoot } from './index.ts';
import { pendingFromList, requireMigrations } from './require-migrations.ts';

const CONFIG = `// Generated by apps/api/scripts/gen-wrangler.ts from envs/x.json: edit the manifest, not this file.\n${JSON.stringify({ name: 'hana-api', d1_databases: [{ binding: 'DB', database_name: 'hana-x', database_id: 'id', migrations_dir: 'migrations' }] })}\n`;
const ARGS = ['--binding', 'DB', '--required', '0034_origin_confirmations.sql'];
const LIST_NONE = '✅ No migrations to apply!';
const listOf = (files: string[]) => `Migrations to be applied:\n┌──────┐\n${files.map((f) => `│ ${f} │`).join('\n')}\n└──────┘`;

describe('requireMigrations', () => {
  it('passes when the database has every migration up to the required one (later ones may wait)', () => {
    const calls: string[][] = [];
    const wrangler = (argv: string[]) => (calls.push(argv), { status: 0, output: LIST_NONE });
    expect(requireMigrations(ARGS, { read: () => CONFIG, wrangler })).toBeNull();
    expect(calls).toEqual([['d1', 'migrations', 'list', 'hana-x', '--remote']]);
    expect(requireMigrations(ARGS, { read: () => CONFIG, wrangler: () => ({ status: 0, output: listOf(['0035_later.sql']) }) })).toBeNull();
  });

  it('refuses when the required migration, or one before it, is not applied', () => {
    expect(requireMigrations(ARGS, { read: () => CONFIG, wrangler: () => ({ status: 0, output: listOf(['0034_origin_confirmations.sql']) }) })).toMatch(/lacks 0034_origin_confirmations\.sql/u);
    expect(requireMigrations(ARGS, { read: () => CONFIG, wrangler: () => ({ status: 0, output: listOf(['0033_platform_ops.sql', '0034_origin_confirmations.sql']) }) })).toMatch(/lacks 0033_platform_ops\.sql, 0034_origin_confirmations\.sql/u);
  });

  it('fails closed: no config, no such binding, wrangler failing or printing something else, bad arguments', () => {
    const ok = () => ({ status: 0, output: LIST_NONE });
    expect(requireMigrations(ARGS, { read: () => { throw new Error('ENOENT'); }, wrangler: ok })).toMatch(/can't read wrangler\.jsonc/u);
    expect(requireMigrations(ARGS, { read: () => '{not json', wrangler: ok })).toMatch(/can't read/u);
    expect(requireMigrations(['--binding', 'OTHER', '--required', '0034_origin_confirmations.sql'], { read: () => CONFIG, wrangler: ok })).toMatch(/no D1 database bound as OTHER/u);
    expect(requireMigrations(ARGS, { read: () => CONFIG, wrangler: () => ({ status: 1, output: 'Authentication error' }) })).toMatch(/failed \(exit 1\)/u);
    expect(requireMigrations(ARGS, { read: () => CONFIG, wrangler: () => ({ status: 0, output: 'something new' }) })).toMatch(/printed something unexpected/u);
    expect(requireMigrations(['--binding', 'DB'], { read: () => CONFIG, wrangler: ok })).toMatch(/usage/u);
    expect(requireMigrations(['--binding', 'DB', '--required', 'latest'], { read: () => CONFIG, wrangler: ok })).toMatch(/usage/u);
    expect(pendingFromList('')).toBeNull();
  });

  it('each app’s deploy requires its latest migration (a new migration the code reads updates the script)', () => {
    for (const [app, binding] of [
      ['api', 'DB'],
      ['console', 'CONSOLE_DB'],
    ] as const) {
      const deploy = (JSON.parse(readFileSync(join(repoRoot, 'apps', app, 'package.json'), 'utf8')) as { scripts: Record<string, string> }).scripts.deploy!;
      const latest = readdirSync(join(repoRoot, 'apps', app, 'migrations')).filter((f) => f.endsWith('.sql')).sort().at(-1);
      expect(deploy, app).toMatch(new RegExp(`^tsx \\.\\./\\.\\./packages/env/src/check-migrations\\.ts --binding ${binding} --required ${latest} && `, 'u'));
    }
  });
});
